import{_ as a,o as e,c as t,a5 as r}from"./chunks/framework.DOB-AMqW.js";const m=JSON.parse('{"title":"Stillora Support","description":"Standalone support information for the Stillora application.","frontmatter":{"title":"Stillora Support","description":"Standalone support information for the Stillora application.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"support/stillora.md","filePath":"support/stillora.md"}'),l={name:"support/stillora.md"};function i(n,o,s,p,d,c){return e(),t("div",null,[...o[0]||(o[0]=[r('<h1 id="stillora-support" tabindex="-1">Stillora Support <a class="header-anchor" href="#stillora-support" aria-label="Permalink to &quot;Stillora Support&quot;">​</a></h1><p>For Stillora support, email <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p><p>Include the Stillora version, Android version, device model, a description of the issue, and safe reproduction steps when possible.</p><p>Do not email personal information or an unreviewed backup file.</p><h2 id="common-help" tabindex="-1">Common help <a class="header-anchor" href="#common-help" aria-label="Permalink to &quot;Common help&quot;">​</a></h2><ul><li><strong>No sound:</strong> check Android media volume, the in-app volume control, connected Bluetooth devices, and whether another app controls audio output.</li><li><strong>A sound does not start:</strong> pause playback, choose another atmosphere, and reopen Stillora if needed. Audio is bundled and does not require streaming.</li><li><strong>Timer stops playback:</strong> choose a new duration or <strong>Continuous</strong>, then start playback again.</li><li><strong>Backup import fails:</strong> select a valid Stillora JSON backup created by the app. Files larger than the supported backup limit or invalid JSON are rejected.</li><li><strong>Settings missing after reinstalling:</strong> import a backup saved before the app was removed. Stillora does not provide cloud sync.</li></ul>',6)])])}const f=a(l,[["render",i]]);export{m as __pageData,f as default};
